    output.push_str(&denia_core::preset::PresetFeatures::decl(&config));
    output.push_str("\n\n");
    output.push_str("export ");
    output.push_str(&denia_core::preset::AgentPreset::decl(&config));
    output.push_str("\n\n");
    output.push_str("export ");
    output.push_str(&denia_core::preset::PresetSpec::decl(&config));
    output.push_str("\n\n");
    output.push_str("export ");
    output.push_str(&denia_core::session::SessionHeader::decl(&config));
    output.push_str("\n\n");
    output.push_str("export ");
    output.push_str(&denia_core::session::SubagentDescriptor::decl(&config));
    output.push_str("\n\n");
    output.push_str("export ");
    output.push_str(&denia_core::session::SubagentProfileRef::decl(&config));
    output.push_str("\n\n");
    output.push_str("export ");
    output.push_str(&denia_core::session::SubagentForkProjection::decl(&config));
    output.push_str("\n\n");
    output.push_str("export ");
    output.push_str(&denia_core::session::LegacySubagentInfo::decl(&config));
    output.push_str("\n\n");
    output.push_str("export ");
    output.push_str(&denia_core::subagent::ProfileSource::decl(&config));
    output.push_str("\n\n");
    output.push_str("export ");
    output.push_str(&denia_core::subagent::ToolSelection::decl(&config));
    output.push_str("\n\n");
    output.push_str("export ");
    output.push_str(&denia_core::subagent::ModelChoice::decl(&config));
    output.push_str("\n\n");
    output.push_str("export ");
    output.push_str(&denia_core::subagent::PermissionCeiling::decl(&config));
    output.push_str("\n\n");
    output.push_str("export ");
    output.push_str(&denia_core::subagent::ProfileColor::decl(&config));
    output.push_str("\n\n");
    output.push_str("export ");
    output.push_str(&denia_core::subagent::ProfileWriteScope::decl(&config));
    output.push_str("\n\n");
    output.push_str("export ");
    output.push_str(&denia_core::subagent::SubagentProfile::decl(&config));
    output.push_str("\n\n");
    output.push_str("export ");
    output.push_str(&denia_core::subagent::SubagentInlineSpec::decl(&config));
    output.push_str("\n\n");
    output.push_str("export ");
    output.push_str(&denia_core::subagent::ProfileDiagnostic::decl(&config));
    output.push_str("\n\n");
    output.push_str("export ");
    output.push_str(&denia_core::subagent::SubagentProfileView::decl(&config));
    output.push_str("\n\n");
    output.push_str("export ");
    output.push_str(&denia_core::subagent::SubagentCatalogEntry::decl(&config));
    output.push_str("\n\n");
    output.push_str("export ");
    output.push_str(&denia_core::session::SessionHeaderKind::decl(&config));
    output.push_str("\n\n");
    output.push_str("export ");
    output.push_str(&denia_core::session::TurnEndReason::decl(&config));
    output.push_str("\n\n");
    output.push_str("export ");
    output.push_str(&denia_core::session::AbortCause::decl(&config));
    output.push_str("\n\n");
