    output.push_str("export ");
    output.push_str(&denia_core::session::AskOption::decl(&config));
    output.push_str("\n\n");
    output.push_str("export ");
    output.push_str(&denia_core::session::AskQuestion::decl(&config));
    output.push_str("\n\n");
